package Distinct_Subsequences_II;

import java.util.Arrays;

public class Solution3 {
	int dp[];
	int[] prevIndex;
	int MOD = 1_000_000_007;
	public int distinctSubseqII(String s) {
        int n = s.length();
        dp = new int[n+1];
        Arrays.fill(dp, -1);
        
        prevIndex = new int[n+1];
        
        int[] lastSeen = new int[26];
        Arrays.fill(lastSeen, -1);
        
        for(int i=1;i<=n;i++) {
        	int idx = s.charAt(i-1) - 'a';
        	prevIndex[i] = lastSeen[idx];
        	lastSeen[idx] = i;
        }
        
        return (solve(n) - 1 + MOD) % MOD;
    }
	
	private int solve(int n) {
		if(n == 0) {
			return 1;
		}
		
		if(dp[n] != -1) {
			return dp[n];
		}
		
		int total = (2* solve(n-1)) % MOD;
		
		if(prevIndex[n] != -1) {
			int duplicate = solve(prevIndex[n] - 1) % MOD;
			total = (total - duplicate + MOD) % MOD;
		}
		
		return dp[n] = total;
	}

    public static void main(String[] args) {
    	String s = "";
    	
    	Solution3 sol3 = new Solution3();
    	System.out.println("Output: " + sol3.distinctSubseqII(s));
	}
}